edits.replacement:
#root #kitsetup .kst span, #root #kitsetup .kstc span, #root #kitsetup .ksreset{ font-size:var(--fs-label); }
/* v28.xx (cw-uc-stash3) b-31 step 7, critic on 04 (P1 "key names inside gun keys and wheel about 11px bold... under the 16px floor", P0 "the version stamp is the title area"): the gun key and item wheel names, the section captions and the reset buttons go from 14px to the 16px label size, names lose their letter spacing so shotgun and carbine still fit; the build stamp beside PILLAGERS is hidden in the Undercroft (it stays in the F1 and settings pages). */
#root #kitsetup .kst span{ letter-spacing:0; }
#root #hub #verlabel{ display:none; }

check:
{v:'VER',what:'the stash gun key and item wheel names are at the 16px label size and the build stamp is gone from the stash header',
 run:function(){
   if(!window.__hubEnter||!window.__station) return 'SKIP: this fixture cannot walk the Undercroft';
   var bad=[], els, i, el, fs, vl;
   try{
     __topClear(); __runPrep(); __cleanProfile(); __wnseen(1);
     __hubEnter(); __station('term','KeyE');
     el=document.querySelector('#kitsetup .kst span');
     if(!el) return 'SKIP: no gun keys drawn';
     fs=parseFloat(getComputedStyle(el).fontSize);
     if(!(fs>=15.5)) bad.push('the gun key names are '+fs+'px, under the 16px floor');
     fs=parseFloat(getComputedStyle(document.querySelector('#kitsetup .ksreset')).fontSize);
     if(!(fs>=15.5)) bad.push('the reset buttons are '+fs+'px');
     vl=document.getElementById('verlabel');
     if(vl&&getComputedStyle(vl).display!=='none') bad.push('the build stamp still shows in the stash header');
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{ try{ var hb=document.getElementById('hub'); if(hb) hb.classList.remove('on'); }catch(_h){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
